CREATE FUNCTION [stripe].[fnpayoutreversed_by_GetRootID]
(
    @RecordID nvarchar(450),
    @ParentID nvarchar(450)
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [id],
            [reversed_by],
            [id] AS [RootParentID],
            0 AS [Depth]
        FROM
            [stripe].[payout]
        WHERE
            [id] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[id],
            c.[reversed_by],
            c.[id] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [stripe].[payout] c
        INNER JOIN
            CTE_RootParent p ON c.[id] = p.[reversed_by]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [reversed_by] IS NULL
    ORDER BY
        [RootParentID]
);
GO

